-- Test objects for test/pg-test.js (recreated on every run, in schema lookup_test).
DROP SCHEMA IF EXISTS lookup_test CASCADE;
CREATE SCHEMA lookup_test;
SET search_path = lookup_test;

CREATE TYPE mood AS ENUM ('sad', 'ok', 'happy');
CREATE DOMAIN positive_int AS integer CHECK (VALUE > 0);

CREATE TABLE customers (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  email text UNIQUE,
  city text DEFAULT 'Cairo',
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE customers IS 'People who buy things';
COMMENT ON COLUMN customers.email IS 'Login e-mail';

CREATE TABLE orders (
  id bigserial PRIMARY KEY,
  customer_id integer NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
  amount numeric(12, 2) NOT NULL CHECK (amount >= 0),
  placed_on date NOT NULL,
  placed_at timestamp(3),
  details jsonb,
  tags text[],
  photo bytea,
  feeling mood,
  qty positive_int,
  "Mixed Case" text
);
CREATE INDEX orders_placed_on_idx ON orders (placed_on DESC);

CREATE TABLE audit_log (at timestamptz DEFAULT now(), message text);

INSERT INTO customers (name, email, city, created_at)
SELECT 'Customer ' || g, 'c' || g || '@example.com', (ARRAY['Cairo', 'Giza', 'Alexandria'])[1 + g % 3], timestamptz '2026-01-01 10:00:00+00' + g * interval '1 hour'
  FROM generate_series(1, 200) g;
INSERT INTO orders (customer_id, amount, placed_on, placed_at, details, tags, photo, feeling, qty, "Mixed Case")
SELECT 1 + g % 200, round((g * 1.37)::numeric, 2), date '2026-01-01' + g % 90, timestamp '2026-01-01 08:30:00.123' + g * interval '1 minute',
       jsonb_build_object('n', g, 'gift', g % 7 = 0), ARRAY['t' || g % 5, 'x'], decode('DEADBEEF', 'hex'),
       (ARRAY['sad', 'ok', 'happy']::mood[])[1 + g % 3], 1 + g % 9, 'v' || g
  FROM generate_series(1, 1000) g;
INSERT INTO audit_log (message) VALUES ('first'), ('second');

CREATE VIEW big_orders AS SELECT o.id, c.name, o.amount FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.amount > 1000;
CREATE MATERIALIZED VIEW city_counts AS SELECT city, count(*) AS n FROM customers GROUP BY city;
CREATE SEQUENCE invoice_no START WITH 1000 INCREMENT BY 10;

CREATE FUNCTION order_total(cid integer) RETURNS numeric LANGUAGE sql STABLE AS $$
  SELECT coalesce(sum(amount), 0) FROM lookup_test.orders WHERE customer_id = cid;
$$;
CREATE PROCEDURE touch_log(msg text) LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO lookup_test.audit_log (message) VALUES (msg);
  RAISE NOTICE 'logged %', msg;
END;
$$;
CREATE FUNCTION log_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO lookup_test.audit_log (message) VALUES (TG_OP || ' on customers');
  RETURN NEW;
END;
$$;
CREATE TRIGGER customers_audit AFTER UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION log_change();
